(7048624, 1070771, 12611, '<td valign="top">The lighting is nice, on the hands, on the sill- a terrifically poignant inside-or out feel, and a good choice to shoot in color.</td>', 'The lighting is nice, on the hands, on the sill- a terrifically poignant inside-or out feel, and a good choice to shoot in color.', '2013-06-06 10:03:49.000000', NULL, 1),
